#!/usr/bin/env node
/**
 * Asserts the built document is actually a document.
 *
 * The unit tests, the type checker and the linter all pass happily when a build
 * produces a shell with no content in it. That is the specific failure this site
 * is most able to have, because its HTML is generated by a prerender step rather
 * than written by hand. If that step silently stops working — an import fails, a
 * chunk name changes, a plugin reorders the output — the page would still build
 * green and serve a blank document to every crawler that does not run
 * JavaScript.
 *
 * Run against `dist/` after the build. Exits non-zero on the first failure.
 */
import { readFile, stat } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'dist');
const failures = [];
const check = (ok, message) => { if (!ok) failures.push(message); };

const read = async (file) => readFile(join(root, file), 'utf8');
const exists = async (file) => {
  try { await stat(join(dist, file)); return true; } catch { return false; }
};

const html = await read('dist/index.html');
const siteSource = await read('src/data/site.ts');
// Vite reformats the built HTML across lines, so tag matching runs on a flattened
// copy. Content assertions run on the original.
const flat = html.replace(/\s+/g, ' ');

// `<noscript>` content is never parsed as elements by a browser that has
// JavaScript, so its heading is not a second document heading. It is stripped
// before structural checks and kept for the text checks.
const withoutNoscript = html.replace(/<noscript>[\s\S]*?<\/noscript>/g, ' ');
const noscript = html.match(/<noscript>([\s\S]*?)<\/noscript>/)?.[1] ?? '';

// --- The document itself ---------------------------------------------------
check(html.startsWith('<!doctype html>'), 'index.html does not start with a doctype');
check(flat.includes('<html lang="en"'), 'the html element has no lang');
check(flat.includes('<meta name="viewport"'), 'no viewport meta tag');
check(flat.includes('<meta name="description"'), 'no meta description');
check(flat.includes('rel="canonical"'), 'no canonical link');
check(flat.includes('property="og:title"'), 'no Open Graph title');
check(flat.includes('property="og:image"'), 'no Open Graph image');
check(flat.includes('property="og:description"'), 'no Open Graph description');
check(flat.includes('name="twitter:card"'), 'no Twitter card type');
check(flat.includes('rel="manifest"'), 'no web manifest link');

// Every description the document publishes must be the same sentence. They were
// three different ones — the meta tag, the Open Graph tag and the JSON-LD
// Organization all described the company differently, which is exactly what a
// search engine or a link preview compares.
const descriptions = [
  ['meta description', flat.match(/<meta name="description"[^>]*content="([^"]*)"/)?.[1]],
  ['og:description', flat.match(/<meta property="og:description"[^>]*content="([^"]*)"/)?.[1]],
  ['twitter:description', flat.match(/<meta name="twitter:description"[^>]*content="([^"]*)"/)?.[1]],
];
for (const [label, value] of descriptions) {
  check(Boolean(value), `no ${label}`);
}
const distinct = new Set(descriptions.map(([, value]) => value));
check(
  distinct.size === 1,
  `the published descriptions disagree: ${[...distinct].map((d) => `"${d?.slice(0, 40)}..."`).join(' vs ')}`,
);

// And they must match the one in the data, which is also what the structured
// data and the web manifest publish.
const dataDescription = siteSource.match(/description:\s*\n?\s*'([^']+)'/)?.[1];
check(
  descriptions[0][1] === dataDescription,
  `the meta description is not site.description; update index.html's development-time copy`,
);
check(flat.includes('src="/theme-init.js"'), 'the theme bootstrap script is not referenced');
check(!/<script>(?![\s\S]{0,4}type=)/.test(flat.replace(/<script type="application\/ld\+json">/g, '')), 'an inline script was reintroduced, which the CSP would block');

// --- The prerender, which is the part that can silently stop working ---------
const body = html.split('<div id="root">')[1] ?? '';
check(body.length > 1000, 'the root is empty: the prerender step did not inject the app');
check(/^<div class="min-h-screen/.test(body), 'the injected markup does not look like the app');

const visibleText = body
  .replace(/<script[\s\S]*?<\/script>/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

check(visibleText.length > 4000, `only ${visibleText.length} characters of body text; a prerendered page should be far more`);
for (const fragment of ['Build. Connect.', 'Hilbras SDK', 'Six areas', 'How everything connects', 'Build what comes']) {
  check(visibleText.includes(fragment), `"${fragment}" is missing from the static HTML`);
}
check(noscript.length > 200, 'the noscript fallback is empty');
check(/Hilbras/.test(noscript), 'the noscript fallback does not say what the site is');

// --- Heading structure ------------------------------------------------------
const h1s = withoutNoscript.match(/<h1[\s>]/g) ?? [];
check(h1s.length === 1, `expected exactly one h1 outside noscript, found ${h1s.length}`);
check(/<h2[\s>]/.test(withoutNoscript), 'no h2 in the document');
check(!/<h4[\s>]/i.test(withoutNoscript), 'an h4 appears without an h3 above it');
const articles = withoutNoscript.match(/<article[\s>]/g) ?? [];
check(articles.length >= 11, `expected at least 11 product articles, found ${articles.length}`);

// --- Links ------------------------------------------------------------------
const deadAnchors = [...new Set(
  [...withoutNoscript.matchAll(/href="#([^"]*)"/g)]
    .map((m) => m[1])
    .filter((id) => id && !withoutNoscript.includes(`id="${id}"`)),
)];
check(deadAnchors.length === 0, `anchors with no matching id: ${deadAnchors.join(', ')}`);

// --- Structured data --------------------------------------------------------
const ldBlocks = html.match(/<script type="application\/ld\+json">[\s\S]*?<\/script>/g) ?? [];
check(ldBlocks.length === 1, `expected one JSON-LD block, found ${ldBlocks.length}`);
if (ldBlocks.length === 1) {
  try {
    const parsed = JSON.parse(ldBlocks[0].replace(/<\/?script[^>]*>/g, ''));
    check(parsed['@context'] === 'https://schema.org', 'JSON-LD has the wrong @context');
    const graph = parsed['@graph'] ?? [];
    check(graph.length >= 13, `JSON-LD graph has ${graph.length} nodes, expected at least 13`);
    const types = graph.map((n) => n['@type']);
    for (const type of ['Organization', 'WebSite', 'OperatingSystem', 'SoftwareSourceCode']) {
      check(types.includes(type), `JSON-LD has no ${type} node`);
    }
  } catch (error) {
    failures.push(`JSON-LD does not parse: ${error.message}`);
  }
}

// --- Generated files --------------------------------------------------------
for (const file of ['robots.txt', 'sitemap.xml', 'site.webmanifest', 'favicon.svg', 'og.png']) {
  check(await exists(file), `${file} was not generated into dist/`);
}
// The manifest is a claim about files that must exist at declared dimensions.
// A manifest referencing a missing or wrongly-sized icon fails silently on
// every platform, so it is checked rather than assumed.
const manifest = JSON.parse(await read('dist/site.webmanifest'));
for (const field of ['name', 'short_name', 'start_url', 'display', 'background_color', 'theme_color']) {
  check(Boolean(manifest[field]), `the web manifest has no ${field}`);
}
check(Array.isArray(manifest.icons) && manifest.icons.length > 0, 'the web manifest has no icons');

const declared = /(\d+)x(\d+)/;
for (const icon of manifest.icons ?? []) {
  const file = join(dist, icon.src.replace(/^\//, ''));
  try {
    await stat(file);
  } catch {
    failures.push(`the web manifest references ${icon.src}, which is not in dist/`);
    continue;
  }
  if (!icon.src.endsWith('.png') || !declared.test(icon.sizes)) continue;

  // Read the PNG header directly rather than decoding the image: the IHDR chunk
  // carries the dimensions in the first 24 bytes.
  const { readFile: readBinary } = await import('node:fs/promises');
  const header = await readBinary(file);
  const signature = [0x89, 0x50, 0x4e, 0x47].every((byte, index) => header[index] === byte);
  if (!signature) {
    failures.push(`${icon.src} is not a PNG`);
    continue;
  }
  const width = header.readUInt32BE(16);
  const height = header.readUInt32BE(20);
  const [wantWidth, wantHeight] = icon.sizes.split('x').map(Number);
  check(
    width === wantWidth && height === wantHeight,
    `${icon.src} declares ${icon.sizes} but is ${width}x${height}`,
  );
}
check(
  (manifest.icons ?? []).some((icon) => icon.purpose === 'maskable'),
  'the web manifest has no maskable icon, so Android launchers will crop the standard one',
);
check(
  (manifest.icons ?? []).some((icon) => icon.sizes === '192x192'),
  'the web manifest has no 192x192 icon, which is the size Android requires',
);

const robots = await read('dist/robots.txt');
check(robots.includes('Sitemap:'), 'robots.txt does not advertise the sitemap');
const sitemap = await read('dist/sitemap.xml');
check(sitemap.includes('<urlset'), 'sitemap.xml is not a urlset');
check(sitemap.includes('<loc>'), 'sitemap.xml has no locations');

// --- The canonical domain, used consistently and named nowhere else ---------
const site = siteSource.match(/domain: '([^']+)'/)?.[1];
check(Boolean(site), 'could not read site.domain from src/data/site.ts');

if (site) {
  check(site.endsWith('/') === false, 'site.domain should not end with a slash, or every joined URL doubles it');

  // The build may have been given a different origin through SITE_URL, which is
  // how a preview deployment gets its own identity. When it has, every published
  // URL must follow it — a preview serving the production canonical is the exact
  // failure this guards, and it is invisible until a crawler indexes it.
  const override = process.env.SITE_URL?.trim().replace(/\/+$/, '');
  const expected = override && /^https?:\/\//.test(override) ? override : site;
  if (override && expected !== site) {
    console.log(`build output: asserting against the SITE_URL origin ${expected}`);
    check(
      !flat.includes(`${site}/#`),
      `the build published ${site} JSON-LD identifiers despite SITE_URL=${override}`,
    );
  }

  const canonical = flat.match(/rel="canonical" href="([^"]+)"/)?.[1];
  check(canonical === `${expected}/`, `canonical is ${canonical}, expected ${expected}/`);

  // External hosts that are legitimately published: the organisation's GitHub
  // and any product site in the data. Anything else is a hardcoded domain that
  // survived a migration.
  // Both origins are legitimate: the committed one for a normal build, and the
  // SITE_URL one when the build was overridden. Anything else is a stray.
  const allowed = new Set([
    site.replace(/\/$/, ''),
    expected.replace(/\/$/, ''),
    'https://github.com',
    'https://schema.org',
    // SPDX identifiers for the licence a published package ships under.
    'https://spdx.org',
  ]);
  for (const source of [await read('src/data/site.ts'), await read('src/data/areas.ts')]) {
    for (const product of source.match(/href: '(https:[^']+)'/g) ?? []) {
      allowed.add(new URL(product.match(/'(https:[^']+)'/)[1]).origin);
    }
  }
  // The rule is one sentence: **a bare URL is a claim about where something
  // lives; a URL inside a sentence is content.**
  //
  // Scanning the whole document flagged a product description that mentioned
  // `https://example.com/?a=1&b=2` — which is not a defect, it is a developer
  // tools product describing a query string. But the description also flows
  // into the JSON-LD, so narrowing to attributes was not enough on its own.
  //
  // So every string the document publishes is examined, and only the ones that
  // *are* a URL — the value starts with a scheme and nothing else. That covers
  // `href`, `src`, `og:url`, `@id`, `codeRepository` and every other URL-valued
  // field, without caring which construct it arrived in, and it cannot be
  // defeated by moving a stray origin into prose.
  const PROSE_KEYS = new Set(['description', 'abstract', 'text', 'body', 'name']);
  const claimOrigins = [];
  const consider = (value, key) => {
    if (typeof value !== 'string') return;
    if (key && PROSE_KEYS.has(key)) return;
    const trimmed = value.trim();
    if (!/^https?:\/\//i.test(trimmed)) return;
    try {
      claimOrigins.push({ origin: new URL(trimmed.split(/\s+/)[0]).origin, value: trimmed });
    } catch {
      /* not a URL after all */
    }
  };
  const walk = (node, key) => {
    if (Array.isArray(node)) return node.forEach((entry) => walk(entry, key));
    if (node && typeof node === 'object') {
      for (const [childKey, child] of Object.entries(node)) walk(child, childKey);
      return;
    }
    consider(node, key);
  };

  for (const match of html.matchAll(/\b(?:href|src)="([^"]*)"/g)) consider(match[1]);
  for (const match of html.matchAll(/<meta\b[^>]*\bcontent="([^"]*)"/g)) consider(match[1]);
  for (const block of html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)) {
    try {
      walk(JSON.parse(block[1]));
    } catch {
      failures.push('a JSON-LD block does not parse');
    }
  }

  for (const { origin, value } of claimOrigins) {
    if (!allowed.has(origin)) {
      failures.push(`an unexpected external origin is published: ${origin} (${value.slice(0, 70)})`);
    }
  }

  for (const [name, content] of [['robots.txt', robots], ['sitemap.xml', sitemap]]) {
    if (!content.includes(expected)) failures.push(`${name} does not reference ${expected}`);
    if (override && expected !== site && content.includes(site)) {
      failures.push(`${name} still references the production origin ${site} despite SITE_URL`);
    }
  }
}

// --- Every route ------------------------------------------------------------
const productIdsForRoutes = [...(await read('src/data/areas.ts')).matchAll(/^    id: '([a-z0-9-]+)',$/gm)]
  // The areas array is the same shape as the products array, so only the block
  // after `export const products` holds product ids.
  .map((m) => m[1]);

// The homepage's section ids, needed to resolve the `/#section` links that
// appear on every other route.
const homeSectionIds = new Set(
  [...html.matchAll(/<(?:section|main)[^>]*id="([^"]+)"/g)].map((m) => m[1]),
);

const blocks = (await read('src/data/areas.ts')).split('export const products')[1] ?? '';
const productIds = [...blocks.matchAll(/^    id: '([a-z0-9-]+)',$/gm)].map((m) => m[1]);
const routes = ['/', '/products', ...productIds.map((id) => `/products/${id}`)];

for (const route of routes) {
  const file = route === '/' ? join(dist, 'index.html') : join(dist, route, 'index.html');
  let document;
  try {
    document = await readFile(file, 'utf8');
  } catch {
    failures.push(`the prerender produced no document for ${route} — expected ${file}`);
    continue;
  }

  const documentFlat = document.replace(/\s+/g, ' ');
  const label = `${route}`.padEnd(20);

  // Injected, not an empty mount point. This is the failure a prerender can have
  // silently, per route rather than across the site.
  if (!/<div id="root"><div/.test(document)) {
    failures.push(`${route}: the prerender injected no markup`);
    continue;
  }

  const text = (document.split('<div id="root">')[1] ?? '')
    .replace(/<script[\s\S]*?<\/script>/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (text.length < 500) failures.push(`${route}: only ${text.length} characters of prerendered text`);

  // Indexable: one title, one description, a canonical naming its own address.
  const title = documentFlat.match(/<title>([^<]+)<\/title>/)?.[1];
  if (!title) failures.push(`${route}: no title`);
  else if (route !== '/' && !/\w/.test(title)) failures.push(`${route}: empty title`);

  const description = documentFlat.match(/<meta name="description"[^>]*content="([^"]*)"/)?.[1];
  if (!description) failures.push(`${route}: no meta description`);

  const canonical = documentFlat.match(/rel="canonical" href="([^"]+)"/)?.[1];
  const wanted = `${site}/${route.replace(/^\//, '')}`;
  if (canonical !== wanted) {
    failures.push(`${route}: canonical is ${canonical}, expected ${wanted}`);
  }

  // The route's own address, not the homepage's. A product page serving the
  // homepage's canonical tells a search engine the two are the same document.
  const routeIds = [...document.matchAll(/#product-([a-z0-9-]+)/g)].map((m) => m[1]);
  if (route.startsWith('/products/')) {
    const own = route.split('/').pop();
    if (!routeIds.includes(own)) failures.push(`${route}: its JSON-LD does not describe ${own}`);
    // Only the organisation, the website and itself. Describing all eleven
    // products on every page makes each page's structured data assert things
    // about products it is not about.
    if (routeIds.length > 1) {
      failures.push(`${route}: JSON-LD describes ${routeIds.length} products, expected only its own`);
    }
  }

  const ld = document.match(/<script type="application\/ld\+json">/g) ?? [];
  if (ld.length !== 1) failures.push(`${route}: expected one JSON-LD block, found ${ld.length}`);

  const h1s = (document.replace(/<noscript>[\s\S]*?<\/noscript>/g, ' ').match(/<h1[\s>]/g) ?? []).length;
  if (h1s !== 1) failures.push(`${route}: expected exactly one h1, found ${h1s}`);

  // A bare `#id` is a same-document anchor and must resolve here. A root-relative
  // `/#id` points at a section of the homepage, so it is resolved against the
  // homepage's document instead — checking it here is how the product pages
  // reported a working link to the closing call to action as broken.
  const documentIds = new Set([...document.matchAll(/id="([^"]+)"/g)].map((m) => m[1]));
  const homeIds = route === '/' ? documentIds : homeSectionIds;
  const dead = [
    ...new Set([
      ...[...document.matchAll(/href="#([^"]*)"/g)]
        .map((m) => m[1])
        .filter((id) => id && !documentIds.has(id)),
    ]),
  ];
  if (dead.length) failures.push(`${route}: same-page anchors with no matching id: ${dead.join(', ')}`);

  const deadHome = [
    ...new Set(
      [...document.matchAll(/href="\/#([^"]*)"/g)]
        .map((m) => m[1])
        .filter((id) => id && !homeIds.has(id)),
    ),
  ];
  if (deadHome.length) {
    failures.push(`${route}: links to homepage sections that do not exist: ${deadHome.join(', ')}`);
  }
}

// A real 404 document, marked noindex so it is never indexed as content.
try {
  const notFound = await readFile(join(dist, '404.html'), 'utf8');
  if (!/name="robots" content="noindex/.test(notFound)) {
    failures.push('404.html is not marked noindex');
  }
  if (!/<div id="root"><div/.test(notFound)) failures.push('404.html has no prerendered markup');
} catch {
  failures.push('the prerender produced no 404.html');
}

// Every route in the sitemap, and nothing in the sitemap that does not exist.
const sitemapLocs = [...sitemap.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1].replace(site, ''));
for (const route of routes) {
  if (!sitemapLocs.includes(route)) failures.push(`${route} is missing from the sitemap`);
}
for (const loc of sitemapLocs) {
  if (!routes.includes(loc)) failures.push(`the sitemap lists ${loc}, which is not a route`);
}

// --- Titles and descriptions are display slots, not fields -----------------
//
// A search result shows roughly 600 pixels of title and 920 of description —
// about 60 and 160 characters of ordinary text — and truncates the rest. Text
// past that boundary is written, shipped, indexed, and never read by anyone, so
// an over-long description is not a longer description; it is a short one with a
// tail nobody sees. `/products` sat at 177 characters until this was measured.
//
// The boundaries are pixel widths, not character counts, so they are treated as
// what they are. Past the target it is reported; past the hard limit — where the
// result is not merely truncated but cut mid-word — it fails the build.
const TITLE_TARGET = 60;
const TITLE_LIMIT = 100;
const DESCRIPTION_TARGET = 160;
const DESCRIPTION_LIMIT = 200;

const overTarget = [];
/**
 * Length as a reader sees it.
 *
 * `&amp;` occupies one character in the title bar, not five. Measuring the raw
 * attribute made a 67-character title look like 81, which is a measurement
 * reporting a number nobody can act on.
 */
const displayedLength = (value) => value.replace(/&(?:[a-z]+|#\d+);/gi, 'x').length;

for (const route of routes) {
  const file = route === '/' ? 'dist/index.html' : `dist${route}/index.html`;
  const document = (await read(file)).split(/\s+/).join(' ');

  const title = document.match(/<title>(.*?)<\/title>/)?.[1] ?? '';
  const description = document.match(/<meta name="description" content="([^"]*)"/)?.[1] ?? '';
  const titleLength = displayedLength(title);
  const descriptionLength = displayedLength(description);

  if (titleLength > TITLE_TARGET) {
    overTarget.push(`${route} — title is ${titleLength} characters`);
  }
  check(
    titleLength <= TITLE_LIMIT,
    `${route}: title is ${titleLength} characters, past the ${TITLE_LIMIT} at which a search result cuts it mid-word`,
  );
  check(
    descriptionLength <= DESCRIPTION_LIMIT,
    `${route}: description is ${descriptionLength} characters, past the ${DESCRIPTION_LIMIT} limit`,
  );
  if (descriptionLength > DESCRIPTION_TARGET) {
    overTarget.push(`${route} — description is ${descriptionLength} characters`);
  }
}

// --- Report -----------------------------------------------------------------
if (failures.length) {
  console.error(`build output: ${failures.length} problem(s)\n`);
  for (const failure of failures) console.error(`  - ${failure}`);
  process.exit(1);
}

console.log(
  `build output: ok — ${(html.length / 1024).toFixed(1)} kB document, ` +
    `${visibleText.length} characters of static text, ${articles.length} articles, ` +
    `${ldBlocks.length} JSON-LD block, origin ${site}`,
);
if (overTarget.length) {
  console.log(
    `  past the display target (${TITLE_TARGET} title / ${DESCRIPTION_TARGET} description, ` +
      `truncated in a search result):\n` +
      overTarget.map((entry) => `    - ${entry}`).join('\n'),
  );
}
